package com.hs.listing.model; import com.hs.listing.model.constant.HandoverCondition; import jakarta.persistence.*; import lombok.*; import java.util.UUID;
@Entity @Table(name="listing_furnishing_assets",indexes=@Index(name="idx_listing_furnishing_assets_listing",columnList="listing_id")) @Getter @Setter @NoArgsConstructor public class ListingFurnishingAsset { @Id @Column(length=36) private String id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="listing_id") private Listing listing; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="furnishing_item_id") private FurnishingItem furnishingItem; @Column(name="item_code",length=64) private String itemCode; @Column(name="asset_name",nullable=false) private String assetName; @Column(nullable=false) private Integer quantity; @Enumerated(EnumType.STRING) @Column(name="handover_condition",nullable=false,length=32) private HandoverCondition handoverCondition; @Column(name="condition_note") private String conditionNote; @Column(name="sort_order",nullable=false) private Integer sortOrder; @PrePersist void pre(){if(id==null)id=UUID.randomUUID().toString();} }
